import { type ClassValue, clsx } from 'clsx';
import { extendTailwindMerge } from 'tailwind-merge';

/**
 * tailwind-merge only knows Tailwind's own utilities. The Capsize type scale
 * (`cap-N`, `cap-N-prose`, generated by `pnpm capsize`) is ours, so without
 * this group twMerge kept BOTH sizes when a caller overrode a component's
 * base, e.g. `cap-14 … cap-12`. The stylesheet then decided, and since the
 * generated CSS lists sizes in ascending order, the larger one always won:
 * every "make this smaller" override was silently ignored.
 *
 * A `cap-*` class sets font-size and line-height, so a later one also
 * replaces an earlier `text-<size>` or `leading-*`.
 */
const twMerge = extendTailwindMerge<'cap-size'>({
  extend: {
    classGroups: {
      'cap-size': [{ cap: [(value: string) => /^\d+(-prose)?$/.test(value)] }],
    },
    conflictingClassGroups: {
      'cap-size': ['font-size', 'leading'],
    },
  },
});

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}
